insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tomate farcie', 'Tomates farcies', array['legume farci', 'petit farci']::text[], 'dish', $r$[{"title":"Tomates farcies","intro":"Des tomates garnies d'une farce à la viande et aux herbes, cuites au four avec du riz.","minutes":75,"calories":480,"difficulty":"Facile","imageSearch":"stuffed tomatoes","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":8,"unit":"","have":false},{"name":"chair à saucisse","plural":"chair à saucisse","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":2,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":120,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Coupe le chapeau des tomates, vide-les et garde la pulpe.","timer":null},{"text":"Mélange la chair à saucisse avec l'oignon, l'ail, le persil et la chapelure.","timer":null},{"text":"Remplis les tomates et remets les chapeaux.","timer":null},{"text":"Mets le riz cru au fond du plat avec la pulpe et 20 cl d'eau, pose les tomates dessus et arrose d'huile.","timer":null},{"text":"Enfourne 1 h.","timer":{"label":"Four","min":60}}],"kids":true,"variant":"La classique","change":""},{"title":"Légumes farcis à la provençale","intro":"Les petits farcis niçois, avec tous les légumes du soleil.","minutes":75,"calories":460,"difficulty":"Moyen","imageSearch":"provencal stuffed vegetables","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité niçoise","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"courgette ronde","plural":"courgettes rondes","qty":4,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"chapelure","plural":"chapelure","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Vide les légumes.","timer":null},{"text":"Fais revenir l'oignon, l'ail et la chair des légumes hachée, puis mélange avec la viande, le parmesan et la chapelure.","timer":null},{"text":"Remplis les légumes, arrose d'huile.","timer":null},{"text":"Enfourne 1 h.","timer":{"label":"Four","min":60}}],"variant":"Petits farcis","change":"Tomates, courgettes et poivrons farcis."},{"title":"Tomates farcies végétariennes","intro":"Des tomates farcies au riz et à la feta, à la grecque.","minutes":60,"calories":360,"difficulty":"Facile","imageSearch":"vegetarian stuffed tomatoes rice feta","veg":true,"oven":true,"cold":false,"missing":"","origin":"Inspiration grecque","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":8,"unit":"","have":false},{"name":"riz","plural":"riz","qty":150,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Vide les tomates et hache la pulpe.","timer":null},{"text":"Mélange le riz cru avec la pulpe, l'oignon haché, la feta, les herbes et l'huile.","timer":null},{"text":"Remplis les tomates aux trois quarts et range-les dans un plat avec 10 cl d'eau.","timer":null},{"text":"Enfourne 50 min.","timer":{"label":"Four","min":50}}],"variant":"Végétarienne","change":"Une farce au riz, à la feta et aux herbes remplace la viande."}]$r$::jsonb, 'claude')
