insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('quiche aux legume', 'Quiche aux légumes', array['quiche legume', 'quiche vegetarienne', 'quiche saumon epinard', 'quiche saumon']::text[], 'dish', $r$[{"title":"Quiche aux légumes","intro":"Une quiche colorée aux courgettes, poivrons et tomates.","minutes":55,"calories":420,"difficulty":"Facile","imageSearch":"vegetable quiche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":100,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":50,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule.","timer":null},{"text":"Fais revenir la courgette et le poivron en dés 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs, la crème, le lait, l'emmental, sel et poivre.","timer":null},{"text":"Répartis les légumes et les tomates sur la pâte, verse l'appareil.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}}],"variant":"La classique","change":""},{"title":"Quiche saumon et épinards","intro":"Une quiche gourmande et complète, saumon et épinards.","minutes":55,"calories":480,"difficulty":"Facile","imageSearch":"salmon spinach quiche","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name"