insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('club sandwich', 'Club sandwich', array['sandwich', 'club sandwich poulet']::text[], 'dish', $r$[{"title":"Club sandwich","intro":"Le sandwich à étages : poulet, bacon, œuf, tomate et salade.","minutes":25,"calories":620,"difficulty":"Facile","imageSearch":"club sandwich","veg":false,"oven":false,"cold":true,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":12,"unit":"tranches","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"bacon","plural":"bacon","qty":8,"unit":"tranches","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"salade","plural":"salades","qty":4,"unit":"feuilles","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le poulet 10 min et tranche-le. Fais griller le bacon 4 min.","timer":{"label":"Poêle","min":14}},{"text":"Fais cuire les œufs durs 10 min et coupe-les en rondelles.","timer":{"label":"Œufs","min":10}},{"text":"Toaste le pain et tartine-le de mayonnaise.","timer":null},{"text":"Monte 3 étages : poulet et salade, puis bacon, tomate et œuf.","timer":null},{"text":"Coupe en triangles et pique avec un cure-dent.","timer":null}],"variant":"La classique","change":""},{"title":"Club sandwich au thon","intro":"Le club sandwich en version thon-crudités.","minutes":15,"calories":520,"difficulty":"Facile","imageSearch":"tuna club sandwich","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":12,"unit":"tranches","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"salade","plural":"salades","qty":4,"unit":"feuilles","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les œufs durs 10 min.","timer":{"label":"Œufs","min":10}},{"text":"Mélange le thon avec la mayonnaise.","timer":null},{"text":"Toaste le pain et monte les étages avec le thon, les crudités et l'œuf.","timer":null}],"variant":"Au thon","change":"Du thon remplace le poulet et le bacon."},{"title":"Club sandwich végétarien","intro":"Un club végé, à l'avocat et au cheddar.","minutes":15,"calories":500,"difficulty":"Facile","imageSearch":"vegetarian club sandwich avocado","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":12,"unit":"tranches","have":false},{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":4,"unit":"tranches","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"salade","plural":"salades","qty":4,"unit":"feuilles","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les œufs durs 10 min.","timer":{"label":"Œufs","min":10}},{"text":"Écrase les avocats.","timer":null},{"text":"Toaste le pain et monte les étages avec l'avocat, le cheddar, l'œuf et les crudités.","timer":null}],"variant":"Végétarien","change":"Œuf, avocat et fromage remplacent la viande."}]$r$::jsonb, 'claude')
