rtine-le d'avocat écrasé au citron.","timer":null},{"text":"Fais pocher les œufs 3 min dans l'eau frémissante vinaigrée.","timer":{"label":"Cuisson","min":3}},{"text":"Pose un œuf sur chaque tartine, sale et poivre.","timer":null}],"variant":"Avec un œuf","change":"Un œuf poché sur l'avocat."},{"title":"Avocado toast saumon fumé","intro":"L'avocado toast chic, au saumon fumé.","minutes":10,"calories":340,"difficulty":"Facile","imageSearch":"avocado toast smoked salmon","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pain complet","plural":"pains complets","qty":4,"unit":"tranches","have":false},{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais griller le pain.","timer":null},{"text":"Écrase les avocats avec le jus du citron et tartine-les sur le pain.","timer":null},{"text":"Ajoute le saumon fumé et l'aneth, puis poivre.","timer":null}],"variant":"Au saumon fumé","change":"Du saumon fumé et de l'aneth."}]$r$::jsonb, 'claude')
