20,"difficulty":"Facile","imageSearch":"chicken fajitas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"épices fajitas","plural":"épices fajitas","qty":2,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet, les poivrons et l'oignon en lanières.","timer":null},{"text":"Fais dorer le poulet dans l'huile avec les épices 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les légumes et cuis 6 min, ils doivent rester croquants.","timer":{"label":"Poêle","min":6}},{"text":"Réchauffe les tortillas et garnis-les avec la crème et la poêlée.","timer":null}],"kids":true},{"title":"Burger maison","intro":"Un steak juteux, du cheddar fondu, des crudités et une sauce maison dans un pain brioché.","minutes":25,"calories":720,"difficulty":"Facile","imageSearch":"homemade cheeseburger","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"pain à burger","plural":"pains à burger","qty":4,"unit":"","have":false},{"name":"steak haché","plural":"steaks hachés","qty":4,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":4,"unit":"tranches","have":false},{"name":"tomate","plural":"tomates","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"salade","plural":"sa